def solve_small(N):
    max_m_minus_n = 0
    import itertools
    # We only care about the number of each value, and they must be in increasing order of value.
    # For a fixed set of counts N1, N2, ..., NK, the best arrangement to maximize m is 
    # to put all 1s, then all 2s, then all 3s...
    # Then m = sum(N_i * N_{i+1} * N_{i+2}) and n = sum(N_i * N_{i+1} * N_{i+2} * N_{i+3})

    # Try different K
    for K in range(1, N + 1):
        # Partition N into K positive integers
        def get_partitions(n, k):
            if k == 1:
                yield (n,)
                return
            for i in range(1, n - k + 2):
                for p in get_partitions(n - i, k - 1):
                    yield (i,) + p

        for p in get_partitions(N, K):
            m = 0
            for i in range(K - 2):
                m += p[i] * p[i+1] * p[i+2]
            n = 0
            for i in range(K - 3):
                n += p[i] * p[i+1] * p[i+2] * p[i+3]
            max_m_minus_n = max(max_m_minus_n, m - n)
    return max_m_minus_n

for N in range(1, 16):
    print(f"N={N}, max_m_minus_n={solve_small(N)}")
